import{_ as e,o as i,c as n,a2 as t}from"./chunks/framework.CCtxZRER.js";const k=JSON.parse('{"title":"Kamus Istilah","description":"Arti istilah pergudangan dan teknik yang sering dipakai di Gudang Teknik.","frontmatter":{"title":"Kamus Istilah","description":"Arti istilah pergudangan dan teknik yang sering dipakai di Gudang Teknik.","status":"ditinjau","dasar":"materi presentasi Gudang Teknik dan istilah umum pergudangan","diperbarui":"2026-10-13T00:00:00.000Z","kategori":"Gudang Teknik","sumber":["ppt-gudang-teknik"],"outline":2,"kata_kunci":["glosarium","istilah","kamus","definisi","singkatan"]},"headers":[],"relativePath":"divisi/glosarium.md","filePath":"divisi/glosarium.md"}'),r={name:"divisi/glosarium.md"};function s(l,a,o,u,d,h){return i(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="kamus-istilah" tabindex="-1">Kamus Istilah <a class="header-anchor" href="#kamus-istilah" aria-label="Permalink to &quot;Kamus Istilah&quot;">​</a></h1><p class="lead">Istilah yang sering kamu dengar di Gudang Teknik, dijelaskan dengan bahasa sederhana. Gunakan pencarian (<kbd>Ctrl</kbd> + <kbd>K</kbd>) untuk langsung menuju istilah tertentu.</p><h2 id="umum" tabindex="-1">Umum <a class="header-anchor" href="#umum" aria-label="Permalink to &quot;Umum&quot;">​</a></h2><h3 id="gudang-teknik-warehouse" tabindex="-1">Gudang Teknik (warehouse) <a class="header-anchor" href="#gudang-teknik-warehouse" aria-label="Permalink to &quot;Gudang Teknik (warehouse)&quot;">​</a></h3><p>Tempat menerima, menyimpan, mengelola, memelihara, dan menyalurkan barang teknik untuk mendukung operasional perusahaan.</p><h3 id="user" tabindex="-1">User <a class="header-anchor" href="#user" aria-label="Permalink to &quot;User&quot;">​</a></h3><p>Orang atau bagian yang meminta dan memakai material dari gudang, misalnya teknisi perawatan.</p><h3 id="vendor-supplier" tabindex="-1">Vendor / supplier <a class="header-anchor" href="#vendor-supplier" aria-label="Permalink to &quot;Vendor / supplier&quot;">​</a></h3><p>Pihak luar yang menjual dan mengantar barang ke perusahaan.</p><h3 id="erp" tabindex="-1">ERP <a class="header-anchor" href="#erp" aria-label="Permalink to &quot;ERP&quot;">​</a></h3><p><em>Enterprise Resource Planning</em>, yaitu sistem komputer perusahaan yang menghubungkan data antardivisi. Di Gudang Teknik, ERP dipakai untuk menerima permintaan barang dari divisi lain dan mencatat laporan barang keluar.</p><h3 id="os-ppic" tabindex="-1">OS/PPIC <a class="header-anchor" href="#os-ppic" aria-label="Permalink to &quot;OS/PPIC&quot;">​</a></h3><p>Divisi yang menerima laporan bahwa barang sudah masuk dan sesuai. PPIC (<em>Production Planning and Inventory Control</em>) adalah bagian yang merencanakan produksi dan persediaan.</p><h3 id="surat-tanda-terima" tabindex="-1">Surat tanda terima <a class="header-anchor" href="#surat-tanda-terima" aria-label="Permalink to &quot;Surat tanda terima&quot;">​</a></h3><p>Surat yang ditandatangani staff gudang dan diberikan ke vendor sebagai bukti barang sudah diterima dalam kondisi dan jumlah yang sesuai.</p><h3 id="rak-reservasi" tabindex="-1">Rak reservasi <a class="header-anchor" href="#rak-reservasi" aria-label="Permalink to &quot;Rak reservasi&quot;">​</a></h3><p>Rak khusus tempat barang yang sudah disiapkan untuk divisi pemesan, sampai karyawan divisi itu datang mengambilnya.</p><h3 id="catatan-manual-rak" tabindex="-1">Catatan manual rak <a class="header-anchor" href="#catatan-manual-rak" aria-label="Permalink to &quot;Catatan manual rak&quot;">​</a></h3><p>Catatan tertulis yang ada di setiap rak. Diisi setiap kali barang ditaruh atau diambil dari rak tersebut.</p><h3 id="apd-alat-pelindung-diri-ppe" tabindex="-1">APD (alat pelindung diri) / PPE <a class="header-anchor" href="#apd-alat-pelindung-diri-ppe" aria-label="Permalink to &quot;APD (alat pelindung diri) / PPE&quot;">​</a></h3><p>Perlengkapan untuk melindungi tubuh saat bekerja, seperti helm, sarung tangan, safety shoes, dan goggles. PPE adalah singkatan bahasa Inggrisnya (<em>personal protective equipment</em>).</p><h3 id="k3" tabindex="-1">K3 <a class="header-anchor" href="#k3" aria-label="Permalink to &quot;K3&quot;">​</a></h3><p>Keselamatan dan Kesehatan Kerja, yaitu upaya mencegah kecelakaan dan penyakit akibat kerja.</p><h2 id="inventory" tabindex="-1">Inventory <a class="header-anchor" href="#inventory" aria-label="Permalink to &quot;Inventory&quot;">​</a></h2><h3 id="inventory-persediaan" tabindex="-1">Inventory (persediaan) <a class="header-anchor" href="#inventory-persediaan" aria-label="Permalink to &quot;Inventory (persediaan)&quot;">​</a></h3><p>Seluruh material yang disimpan dan dicatat oleh gudang.</p><h3 id="stock-item" tabindex="-1">Stock item <a class="header-anchor" href="#stock-item" aria-label="Permalink to &quot;Stock item&quot;">​</a></h3><p>Material yang rutin dipakai, sehingga stoknya selalu dijaga.</p><h3 id="non-stock-item" tabindex="-1">Non-stock item <a class="header-anchor" href="#non-stock-item" aria-label="Permalink to &quot;Non-stock item&quot;">​</a></h3><p>Material yang jarang dipakai, sehingga tidak disimpan sebagai stok dan baru dibeli saat dibutuhkan.</p><h3 id="fast-moving" tabindex="-1">Fast moving <a class="header-anchor" href="#fast-moving" aria-label="Permalink to &quot;Fast moving&quot;">​</a></h3><p>Material yang diminta 2 kali atau lebih dalam sebulan.</p><h3 id="slow-moving" tabindex="-1">Slow moving <a class="header-anchor" href="#slow-moving" aria-label="Permalink to &quot;Slow moving&quot;">​</a></h3><p>Material yang diminta 1 kali dalam sebulan.</p><h3 id="cycle-counting" tabindex="-1">Cycle counting <a class="header-anchor" href="#cycle-counting" aria-label="Permalink to &quot;Cycle counting&quot;">​</a></h3><p>Metode menghitung sebagian stok secara bergiliran dan berkala, bukan menghitung seluruh gudang sekaligus. Materi Gudang Teknik juga memakai cara ini untuk menentukan fast dan slow moving.</p><h3 id="critical-stock" tabindex="-1">Critical stock <a class="header-anchor" href="#critical-stock" aria-label="Permalink to &quot;Critical stock&quot;">​</a></h3><p>Material slow moving yang harus selalu tersedia (minimal 1 unit) karena dibutuhkan mendadak, misalnya suku cadang mesin penting.</p><h3 id="write-off" tabindex="-1">Write off <a class="header-anchor" href="#write-off" aria-label="Permalink to &quot;Write off&quot;">​</a></h3><p>Persediaan yang sudah tidak terpakai, misalnya karena salah prediksi, mesinnya sudah tidak dipakai, atau barangnya kedaluwarsa.</p><h3 id="overstock" tabindex="-1">Overstock <a class="header-anchor" href="#overstock" aria-label="Permalink to &quot;Overstock&quot;">​</a></h3><p>Stok berlebih yang tersimpan terlalu lama hingga mutunya bisa turun.</p><h3 id="stok-minimum" tabindex="-1">Stok minimum <a class="header-anchor" href="#stok-minimum" aria-label="Permalink to &quot;Stok minimum&quot;">​</a></h3><p>Batas bawah stok. Jika stok di bawah angka ini, risiko kehabisan barang tinggi.</p><h3 id="stok-maksimum" tabindex="-1">Stok maksimum <a class="header-anchor" href="#stok-maksimum" aria-label="Permalink to &quot;Stok maksimum&quot;">​</a></h3><p>Batas atas stok agar barang tidak menumpuk dan memakan tempat.</p><h3 id="rop-reorder-point" tabindex="-1">ROP (reorder point) <a class="header-anchor" href="#rop-reorder-point" aria-label="Permalink to &quot;ROP (reorder point)&quot;">​</a></h3><p>Titik pemesanan ulang. Saat stok turun sampai angka ini, material perlu dipesan kembali.</p><h3 id="safety-stock" tabindex="-1">Safety stock <a class="header-anchor" href="#safety-stock" aria-label="Permalink to &quot;Safety stock&quot;">​</a></h3><p>Stok cadangan untuk berjaga-jaga jika pemakaian melonjak atau pengiriman terlambat.</p><h3 id="lead-time" tabindex="-1">Lead time <a class="header-anchor" href="#lead-time" aria-label="Permalink to &quot;Lead time&quot;">​</a></h3><p>Waktu tunggu sejak barang dipesan sampai barang tiba di gudang.</p><h3 id="fifo-first-in-first-out" tabindex="-1">FIFO (first in, first out) <a class="header-anchor" href="#fifo-first-in-first-out" aria-label="Permalink to &quot;FIFO (first in, first out)&quot;">​</a></h3><p>Barang yang masuk lebih dulu dikeluarkan lebih dulu, agar tidak ada barang yang terlalu lama tersimpan.</p><h3 id="reservasi" tabindex="-1">Reservasi <a class="header-anchor" href="#reservasi" aria-label="Permalink to &quot;Reservasi&quot;">​</a></h3><p>Permintaan atau pemesanan material oleh user yang sudah tercatat sebelum barang diambil.</p><h2 id="administrasi" tabindex="-1">Administrasi <a class="header-anchor" href="#administrasi" aria-label="Permalink to &quot;Administrasi&quot;">​</a></h2><h3 id="master-material" tabindex="-1">Master material <a class="header-anchor" href="#master-material" aria-label="Permalink to &quot;Master material&quot;">​</a></h3><p>Daftar induk semua material: kode, nama, spesifikasi, satuan, dan lokasi.</p><h3 id="kode-barang" tabindex="-1">Kode barang <a class="header-anchor" href="#kode-barang" aria-label="Permalink to &quot;Kode barang&quot;">​</a></h3><p>Kode unik sebagai identitas satu jenis material, misalnya <code>BRG-MEC-001</code>.</p><h3 id="spesifikasi" tabindex="-1">Spesifikasi <a class="header-anchor" href="#spesifikasi" aria-label="Permalink to &quot;Spesifikasi&quot;">​</a></h3><p>Data teknis yang membedakan satu barang dari barang lain, misalnya tipe dan ukuran.</p><h3 id="satuan" tabindex="-1">Satuan <a class="header-anchor" href="#satuan" aria-label="Permalink to &quot;Satuan&quot;">​</a></h3><p>Ukuran yang dipakai untuk menghitung barang, misalnya pcs, set, meter, kilogram, atau liter.</p><h3 id="mutasi" tabindex="-1">Mutasi <a class="header-anchor" href="#mutasi" aria-label="Permalink to &quot;Mutasi&quot;">​</a></h3><p>Perubahan stok akibat barang masuk, barang keluar, atau perpindahan lokasi.</p><h3 id="saldo" tabindex="-1">Saldo <a class="header-anchor" href="#saldo" aria-label="Permalink to &quot;Saldo&quot;">​</a></h3><p>Jumlah stok yang tercatat pada suatu waktu.</p><h3 id="stock-opname" tabindex="-1">Stock opname <a class="header-anchor" href="#stock-opname" aria-label="Permalink to &quot;Stock opname&quot;">​</a></h3><p>Kegiatan menghitung stok fisik lalu membandingkannya dengan catatan.</p><h3 id="selisih" tabindex="-1">Selisih <a class="header-anchor" href="#selisih" aria-label="Permalink to &quot;Selisih&quot;">​</a></h3><p>Perbedaan antara jumlah stok fisik dan jumlah di catatan.</p><h2 id="material-dan-teknik" tabindex="-1">Material dan teknik <a class="header-anchor" href="#material-dan-teknik" aria-label="Permalink to &quot;Material dan teknik&quot;">​</a></h2><h3 id="bearing" tabindex="-1">Bearing <a class="header-anchor" href="#bearing" aria-label="Permalink to &quot;Bearing&quot;">​</a></h3><p>Komponen yang menopang poros berputar agar gesekannya kecil. Ukurannya biasanya ditulis diameter dalam × diameter luar × tebal.</p><h3 id="seal-dan-gasket" tabindex="-1">Seal dan gasket <a class="header-anchor" href="#seal-dan-gasket" aria-label="Permalink to &quot;Seal dan gasket&quot;">​</a></h3><p>Komponen perapat untuk mencegah kebocoran. Seal umumnya untuk bagian yang bergerak, sedangkan gasket untuk sambungan yang diam.</p><h3 id="coupling" tabindex="-1">Coupling <a class="header-anchor" href="#coupling" aria-label="Permalink to &quot;Coupling&quot;">​</a></h3><p>Penghubung antara dua poros, misalnya poros motor dan poros gearbox.</p><h3 id="fastener" tabindex="-1">Fastener <a class="header-anchor" href="#fastener" aria-label="Permalink to &quot;Fastener&quot;">​</a></h3><p>Komponen pengikat, seperti baut, mur, washer, dan screw.</p><h3 id="fitting-flange-dan-valve" tabindex="-1">Fitting, flange, dan valve <a class="header-anchor" href="#fitting-flange-dan-valve" aria-label="Permalink to &quot;Fitting, flange, dan valve&quot;">​</a></h3><p>Fitting adalah sambungan pipa (elbow, tee). Flange adalah sambungan pipa berbentuk piringan yang dibaut. Valve adalah katup untuk membuka, menutup, atau mengatur aliran.</p><h3 id="consumable" tabindex="-1">Consumable <a class="header-anchor" href="#consumable" aria-label="Permalink to &quot;Consumable&quot;">​</a></h3><p>Bahan habis pakai, seperti oli, grease, amplas, dan cutting disc.</p><h3 id="instrumentasi" tabindex="-1">Instrumentasi <a class="header-anchor" href="#instrumentasi" aria-label="Permalink to &quot;Instrumentasi&quot;">​</a></h3><p>Alat ukur dan sensor, seperti pressure gauge, thermometer, dan transmitter.</p><h3 id="erw" tabindex="-1">ERW <a class="header-anchor" href="#erw" aria-label="Permalink to &quot;ERW&quot;">​</a></h3><p><em>Electric Resistance Welding</em>, yaitu proses pengelasan pipa baja menggunakan arus listrik. Lihat <a href="/WareHouse/perusahaan/">Profil Perusahaan</a>.</p><h3 id="coating" tabindex="-1">Coating <a class="header-anchor" href="#coating" aria-label="Permalink to &quot;Coating&quot;">​</a></h3><p>Lapisan pelindung pada permukaan pipa untuk mencegah korosi.</p><h2 id="indikator-kinerja-gudang" tabindex="-1">Indikator kinerja gudang <a class="header-anchor" href="#indikator-kinerja-gudang" aria-label="Permalink to &quot;Indikator kinerja gudang&quot;">​</a></h2><h3 id="order-fulfillment" tabindex="-1">Order fulfillment <a class="header-anchor" href="#order-fulfillment" aria-label="Permalink to &quot;Order fulfillment&quot;">​</a></h3><p>Seberapa tepat permintaan user dipenuhi.</p><h3 id="on-time" tabindex="-1">On-time <a class="header-anchor" href="#on-time" aria-label="Permalink to &quot;On-time&quot;">​</a></h3><p>Material tersedia tepat waktu saat dibutuhkan.</p><h3 id="space-utilization" tabindex="-1">Space utilization <a class="header-anchor" href="#space-utilization" aria-label="Permalink to &quot;Space utilization&quot;">​</a></h3><p>Seberapa efisien ruang gudang dimanfaatkan.</p><h3 id="stock-accuracy" tabindex="-1">Stock accuracy <a class="header-anchor" href="#stock-accuracy" aria-label="Permalink to &quot;Stock accuracy&quot;">​</a></h3><p>Seberapa sesuai stok fisik dengan catatan sistem.</p>',101)])])}const p=e(r,[["render",s]]);export{k as __pageData,p as default};
